                // $073b4  andi.l #$c1c1c1c1, (a0)+
                {
                    k.cy +%= 20;
                    const s = @as(u32, 0xc1c1c1c1);
                    const e1 = k.a[0];
                    k.a[0] +%= 4;
                    const r = k.rl(e1) & s;
                    k.wl(e1, r);
                    k.logic(u32, r);
                }
                // $073ba  dbra d0, $1738a
                {
                    k.cy +%= 14;
                    const w = k.dv(u16, 0) -% 1;
                    k.setD(u16, 0, w);
                    if (w != 0xFFFF) { if (k.cy >= k.limit) return 0x1738a; continue :sw 0x1738a; }
                }
                // $073be  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            else => return k.bad(pc),
        }
    }

};

